//! Every unit is checked against pint's own numbers.
//!
//! `fixtures/pint_units.tsv` is generated by `research/tools/verify_units.py`
//! from the pint library, not from this crate's table, so the two sides come
//! from independent sources. The generator resolves each name through the same
//! lookup the crate uses, and the expectation is what pint computes.

use runits::{Quantity, unit};

/// The generated fixture: name, factor, the seven dimension exponents, offset.
fn fixture() -> Vec<(String, f64, [i8; 7], f64)> {
    let text = include_str!("fixtures/pint_units.tsv");
    text.lines()
        .filter(|line| !line.starts_with('#') && !line.trim().is_empty())
        .map(|line| {
            let mut fields = line.split('\t');
            let name = fields.next().expect("name").to_owned();
            let factor: f64 = fields.next().expect("factor").parse().expect("factor");
            let dim: Vec<i8> = fields
                .next()
                .expect("dim")
                .split(',')
                .map(|value| value.parse().expect("exponent"))
                .collect();
            let offset: f64 = fields.next().expect("offset").parse().expect("offset");
            (
                name,
                factor,
                dim.try_into().expect("seven exponents"),
                offset,
            )
        })
        .collect()
}

#[test]
fn every_fixture_name_has_the_same_scale_as_pint() {
    let rows = fixture();
    assert!(
        rows.len() > 900,
        "the fixture should hold most of the table"
    );

    let mut failures = Vec::new();
    for (name, factor, dim, offset) in &rows {
        let Ok(found) = unit(name) else {
            failures.push(format!("{name}: not found"));
            continue;
        };
        let expected_dim = runits::Dimension {
            length: dim[0],
            time: dim[1],
            mass: dim[2],
            current: dim[3],
            temperature: dim[4],
            substance: dim[5],
            luminosity: dim[6],
        };
        if found.dimension() != expected_dim {
            failures.push(format!(
                "{name}: dimension {} but pint says {expected_dim}",
                found.dimension()
            ));
            continue;
        }
        // The factor is compared with a relative tolerance, because pint
        // computes it in floating point too.
        if !close(found.factor(), *factor) {
            failures.push(format!(
                "{name}: factor {} but pint says {factor}",
                found.factor()
            ));
        }
        if !close(found.offset(), *offset) {
            failures.push(format!(
                "{name}: offset {} but pint says {offset}",
                found.offset()
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} names disagree with pint:\n{}",
        failures.len(),
        failures[..failures.len().min(20)].join("\n")
    );
}

#[test]
fn conversion_round_trips_through_the_base_unit() {
    // A conversion to the base unit and back must return the original value.
    // This is the affine case that a pure scale change would get wrong.
    for name in ["degC", "degF", "degRe", "K"] {
        let source = unit(name).unwrap();
        let base = Quantity::new(37.0, source).base();
        let back = Quantity::new(base, runits::unit("K").unwrap())
            .to(name)
            .unwrap();
        assert!(
            close(back.value(), 37.0),
            "{name}: 37 round-tripped to {}",
            back.value()
        );
    }
}

#[test]
fn celsius_and_fahrenheit_agree_at_the_fixed_points() {
    let freezing = Quantity::parse("0 degC").unwrap().to("degF").unwrap();
    assert!(close(freezing.value(), 32.0), "got {}", freezing.value());
    let boiling = Quantity::parse("100 degC").unwrap().to("degF").unwrap();
    assert!(close(boiling.value(), 212.0), "got {}", boiling.value());
}

#[test]
fn compound_units_convert() {
    let speed = Quantity::parse("60 km/h").unwrap();
    let metres = speed.to("m/s").unwrap();
    assert!(
        close(metres.value(), 16.666_666_666),
        "got {}",
        metres.value()
    );

    let force = Quantity::parse("1 kg*m/s^2").unwrap();
    let newtons = force.to("N").unwrap();
    assert!(close(newtons.value(), 1.0), "got {}", newtons.value());

    // The same expression written with juxtaposition and `**`.
    let same = Quantity::parse("1 kg m s**-2").unwrap();
    assert!(close(same.to("N").unwrap().value(), 1.0));
}

#[test]
fn a_dimension_mismatch_is_an_error() {
    let mass = Quantity::parse("1 kg").unwrap();
    assert!(mass.to("m").is_err());
}

#[test]
fn a_known_but_unrepresentable_unit_is_not_a_typo() {
    // `dB` is a real unit with a logarithmic scale, so the crate reports it as
    // unsupported rather than as an unknown name.
    match unit("dB") {
        Err(runits::UnknownUnit::Unsupported(_)) => {}
        other => panic!("expected Unsupported, got {other:?}"),
    }
    match unit("planck_length") {
        Err(runits::UnknownUnit::Unsupported(_)) => {}
        other => panic!("expected Unsupported, got {other:?}"),
    }
    match unit("florps") {
        Err(runits::UnknownUnit::Unknown(_)) => {}
        other => panic!("expected Unknown, got {other:?}"),
    }
}

#[test]
fn ppi_is_the_printer_unit_not_pico_times_pi() {
    // A prefix decomposition would read `ppi` as `pico` x `pi`, which is a
    // different quantity. The name table must win.
    match unit("ppi") {
        Err(runits::UnknownUnit::Unsupported(_)) => {}
        other => panic!("expected Unsupported, got {other:?}"),
    }
}

#[test]
fn prefixes_apply_to_a_base_unit() {
    // Each pair is the prefixed unit and the plain unit it is a prefix of, so
    // the assertion compares the scale to the base unit's scale.
    for (prefixed, base, factor) in [
        ("km", "m", 1000.0),
        ("cm", "m", 0.01),
        ("mm", "m", 0.001),
        ("MHz", "Hz", 1.0e6),
        ("kPa", "Pa", 1000.0),
        ("µm", "m", 1.0e-6),
        ("daN", "N", 10.0),
        ("kilometre", "metre", 1000.0),
    ] {
        let found = unit(prefixed).unwrap_or_else(|error| panic!("{prefixed}: {error}"));
        let plain = unit(base).unwrap_or_else(|error| panic!("{base}: {error}"));
        let ratio = found.factor() / plain.factor();
        assert!(
            close(ratio, factor),
            "{prefixed}/{base}: ratio {ratio} but expected {factor}"
        );
    }
}

#[test]
fn a_plural_resolves_to_its_singular() {
    assert_eq!(
        unit("metres").unwrap().factor(),
        unit("metre").unwrap().factor()
    );
}

#[test]
fn a_negative_exponent_parses_with_either_caret() {
    // `-` is not part of a name, so it is only ever the sign of an exponent.
    for text in ["1 mol^-1", "1 mol**-1", "1 / mol"] {
        let quantity = Quantity::parse(text).unwrap_or_else(|error| panic!("{text}: {error}"));
        assert_eq!(quantity.dimension().substance, -1, "{text}");
    }

    // A positive sign is accepted too, as in `s^+1`.
    assert_eq!(Quantity::parse("1 s^+1").unwrap().dimension().time, 1);
}

#[test]
fn a_bare_number_is_dimensionless() {
    let plain = Quantity::parse("12.5").unwrap();
    assert!(plain.dimension().is_dimensionless());
    assert!(close(plain.value(), 12.5));
    assert!(close(plain.to("1").unwrap().value(), 12.5));
}

#[test]
fn the_degree_sign_is_part_of_a_name() {
    // `°C` is a name, not the degree sign followed by a name, so it must not
    // tokenise as `°` and `C`.
    let freezing = Quantity::parse("0 °C").unwrap().to("K").unwrap();
    assert!(close(freezing.value(), 273.15), "got {}", freezing.value());
}

/// Every sum and difference is checked against pint's own arithmetic.
///
/// `fixtures/pint_arithmetic.tsv` is generated by
/// `research/tools/gen_units_arithmetic.py` from the pint library, not from
/// this crate. Each row is two quantities and the number pint returns in the
/// *left* operand's unit, which is the unit pint keeps; a row whose expected
/// value is `-` is one pint refuses (a dimension mismatch, or either operand an
/// affine scale), so the crate must refuse it too.
#[test]
fn every_sum_agrees_with_pint() {
    let text = include_str!("fixtures/pint_arithmetic.tsv");
    let mut agree = 0u32;
    let mut failures = Vec::new();
    for line in text.lines() {
        if line.starts_with('#') || line.trim().is_empty() {
            continue;
        }
        let mut fields = line.split('\t');
        let (Some(left), Some(right), Some(expected)) =
            (fields.next(), fields.next(), fields.next())
        else {
            continue;
        };
        let left = Quantity::parse(left).expect("left operand parses");
        let right = Quantity::parse(right).expect("right operand parses");
        let sum = left.add(right);
        let ok = match (sum, expected) {
            (Ok(found), want) => {
                want != "-"
                    && found.dimension() == left.dimension()
                    && close(found.value(), want.parse::<f64>().expect("number"))
            }
            (Err(_), "-") => true,
            (Err(_), _) => false,
        };
        if ok {
            agree += 1;
        } else {
            failures.push(format!("{left} + {right} (pint says {expected})"));
        }

        // The difference is the same check with the sign of the right operand
        // flipped, so it shares the fixture.
        let difference = left.subtract(right);
        let ok = match (difference, expected) {
            (Ok(found), want) => {
                want != "-"
                    && found.dimension() == left.dimension()
                    && close(
                        found.value(),
                        left.value() - (want.parse::<f64>().expect("number") - left.value()),
                    )
            }
            (Err(_), "-") => true,
            (Err(_), _) => false,
        };
        if ok {
            agree += 1;
        } else {
            failures.push(format!("{left} - {right} (pint says {expected})"));
        }
    }
    assert!(agree > 2_000, "only {agree} sums were compared");
    assert!(
        failures.is_empty(),
        "{} sums disagree with pint:\n{}",
        failures.len(),
        failures[..failures.len().min(20)].join("\n")
    );
}

fn close(left: f64, right: f64) -> bool {
    if right == 0.0 {
        left.abs() < 1e-12
    } else {
        (left - right).abs() <= 1e-9 * right.abs().max(1.0)
    }
}
